   145→    initialize_progressive_balances_cache(state, spec)?;
   146→    state.build_exit_cache(spec)?;
   147→    state.build_committee_cache(RelativeEpoch::Previous, spec)?;
   148→    state.build_committee_cache(RelativeEpoch::Current, spec)?;
   149→    state.update_pubkey_cache()?;
   150→
   151→    let previous_epoch = state.previous_epoch();
   152→    let current_epoch = state.current_epoch();
   153→    let next_epoch = state.next_epoch()?;
   154→    let is_in_inactivity_leak = state.is_in_inactivity_leak(previous_epoch, spec)?;
   155→    let total_active_balance = state.get_total_active_balance()?;
   156→    let churn_limit = state.get_validator_churn_limit(spec)?;
   157→    let activation_churn_limit = state.get_activation_churn_limit(spec)?;
   158→    let finalized_checkpoint = state.finalized_checkpoint();
   159→    let fork_name = state.fork_name_unchecked();
   160→
   161→    let state_ctxt = &StateContext {
   162→        current_epoch,
   163→        next_epoch,
   164→        finalized_checkpoint,
   165→        is_in_inactivity_leak,
   166→        total_active_balance,
   167→        churn_limit,
   168→        fork_name,
   169→    };
   170→
   171→    // Contexts that require immutable access to `state`.
   172→    let slashings_ctxt = &SlashingsContext::new(state, state_ctxt, spec)?;
   173→    let mut next_epoch_cache = PreEpochCache::new_for_next_epoch(state)?;
   174→
   175→    let pending_deposits_ctxt = if fork_name.electra_enabled() && conf.pending_deposits {
   176→        Some(PendingDepositsContext::new(state, spec, &conf)?)
   177→    } else {
   178→        None
   179→    };
   180→
   181→    let mut earliest_exit_epoch = state.earliest_exit_epoch().ok();
   182→    let mut exit_balance_to_consume = state.exit_balance_to_consume().ok();
   183→    let validators_in_consolidations = get_validators_in_consolidations(state);
